fn sort_branch_catalog_entries(branches: &mut [(i64, String)]) {
    branches.sort_by(|(date_a, branch_a), (date_b, branch_b)| {
        let main_order = (branch_b == "main").cmp(&(branch_a == "main"));
        main_order
            .then_with(|| date_b.cmp(date_a))
            .then_with(|| branch_a.cmp(branch_b))
    });
}

fn git_branch_catalog_impl(workspace_path: &str) -> anyhow::Result<GitBranchCatalog> {
    let root = workspace_root(workspace_path)?;
    let Some(repo_root) = git_repo_root(&root) else {
        return Ok(GitBranchCatalog {
            available: false,
            current: None,
            branches: Vec::new(),
            worktrees: Vec::new(),
            error: Some("The selected folder is not a Git repository.".into()),
        });
    };
    let mut command = git_command();
    command.arg("-C").arg(&repo_root).args([
        "for-each-ref",
        "--format=%(committerdate:unix)%09%(refname:short)",
        "refs/heads/",
    ]);
    let output = run_bounded_command(
        &command,
        Duration::from_secs(10),
        None,
        2 * 1024 * 1024,
        64 * 1024,
    )?;
    if !output.succeeded() {
        return Err(bounded_command_error(
            "could not list local branches",
            &output,
        ));
    }
    let mut branches = output
        .stdout
        .lines()
        .filter_map(|line| {
            let (committer_date, branch) = line.split_once('\t')?;
            let branch = branch.trim();
            (!branch.is_empty()).then(|| {
                (
                    committer_date.parse::<i64>().unwrap_or(i64::MIN),
                    branch.to_owned(),
                )
            })
        })
        .collect::<Vec<_>>();
    sort_branch_catalog_entries(&mut branches);
    let branches = branches
        .into_iter()
        .map(|(_, branch)| branch)
        .collect::<Vec<_>>();
    let mut current_command = git_command();
    current_command
        .arg("-C")
        .arg(&repo_root)
        .args(["branch", "--show-current"]);
    let current_output = run_bounded_command(
        &current_command,
        Duration::from_secs(10),
        None,
        64 * 1024,
        64 * 1024,
    )?;
    let current = current_output
        .succeeded()
        .then(|| current_output.stdout.trim().to_string());
    let current = current.filter(|branch| !branch.is_empty());
    let worktrees = git_linked_worktrees(&repo_root)?;
    Ok(GitBranchCatalog {
        available: true,
        current,
        branches,
        worktrees,
        error: None,
    })
}

fn git_linked_worktrees(repo_root: &Path) -> anyhow::Result<Vec<GitLinkedWorktree>> {
    let mut command = git_command();
    command
        .arg("-C")
        .arg(repo_root)
        .args(["worktree", "list", "--porcelain"]);
    let output = run_bounded_command(
        &command,
        Duration::from_secs(10),
        None,
        2 * 1024 * 1024,
        64 * 1024,
    )?;
    if !output.succeeded() {
        return Err(bounded_command_error(
            "could not list linked worktrees",
            &output,
        ));
    }

    let mut records = Vec::<(String, Option<String>)>::new();
    let mut path: Option<String> = None;
    let mut branch: Option<String> = None;
    for line in output.stdout.lines().chain(std::iter::once("")) {
        if line.is_empty() {
            if let Some(path) = path.take() {
                records.push((path, branch.take()));
            }
            continue;
        }
        if let Some(value) = line.strip_prefix("worktree ") {
            path = Some(value.to_owned());
        } else if let Some(value) = line.strip_prefix("branch refs/heads/") {
            branch = Some(value.to_owned());
        }
    }

    Ok(records
        .into_iter()
        .skip(1)
        .filter_map(|(path, branch)| branch.map(|branch| GitLinkedWorktree { branch, path }))
        .collect())
}

fn git_remove_worktree_impl(
    request: &GitRemoveWorktreeRequest,
) -> anyhow::Result<GitBranchCatalog> {
    gyro_core::validate_branch_name(&request.branch)?;
    let root = workspace_root(&request.workspace_path)?;
    let repo_root = git_repo_root(&root)
        .ok_or_else(|| anyhow::anyhow!("the selected folder is not a Git repository"))?;
    let worktree = git_linked_worktrees(&repo_root)?
        .into_iter()
        .find(|worktree| worktree.branch == request.branch)
        .ok_or_else(|| anyhow::anyhow!("linked worktree not found"))?;
    if root.canonicalize().ok() == Path::new(&worktree.path).canonicalize().ok() {
        return Err(anyhow::anyhow!("cannot remove the active workspace"));
    }

    let mut command = git_command();
    command
        .arg("-C")
        .arg(&repo_root)
        .args(["worktree", "remove"])
        .arg(&worktree.path);
    let output = run_bounded_command(
        &command,
        Duration::from_secs(60),
        Some(Duration::from_secs(30)),
        2 * 1024 * 1024,
        64 * 1024,
    )?;
    if !output.succeeded() {
        return Err(bounded_command_error("could not remove worktree", &output));
    }
    git_branch_catalog_impl(&request.workspace_path)
}

fn git_checkout_branch_impl(
    request: &GitCheckoutBranchRequest,
) -> anyhow::Result<GitBranchCatalog> {
    gyro_core::validate_branch_name(&request.branch)?;
    let root = workspace_root(&request.workspace_path)?;
    let repo_root = git_repo_root(&root)
        .ok_or_else(|| anyhow::anyhow!("the selected folder is not a Git repository"))?;
    let catalog = git_branch_catalog_impl(&request.workspace_path)?;
    if !catalog
        .branches
        .iter()
        .any(|branch| branch == &request.branch)
    {
        return Err(anyhow::anyhow!("local branch not found"));
    }
    if catalog.current.as_deref() == Some(request.branch.as_str()) {
        return Ok(catalog);
    }
    let mut status_command = git_command();
    status_command
        .arg("-C")
        .arg(&repo_root)
        .args(["status", "--porcelain"]);
    let status = run_bounded_command(
        &status_command,
        Duration::from_secs(10),
        None,
        2 * 1024 * 1024,
        64 * 1024,
    )?;
    if !status.succeeded() {
        return Err(anyhow::anyhow!(
            "could not inspect the workspace before switching branches"
        ));
    }
    if !status.stdout.is_empty() || status.stdout_truncated {
        return Err(anyhow::anyhow!(
            "commit or stash workspace changes before switching branches"
        ));
    }
    let mut switch_command = git_command();
    switch_command
        .arg("-C")
        .arg(&repo_root)
        .arg("switch")
        .arg("--")
        .arg(&request.branch);
    let switched = run_bounded_command(
        &switch_command,
        Duration::from_secs(60),
        Some(Duration::from_secs(30)),
        64 * 1024,
        64 * 1024,
    )?;
    if !switched.succeeded() {
        return Err(bounded_command_error("could not switch branch", &switched));
    }
    git_branch_catalog_impl(&request.workspace_path)
}

