fn test_run_blocking(request: TestRunRequest) -> Result<IdeCommandOutput, String> {
    let _admission = IdeCommandAdmission::acquire()?;
    let root = workspace_root(&request.workspace_path).map_err(to_string)?;
    let discovered = task_discover_impl(&request.workspace_path).map_err(to_string)?;
    let requested_ids = request.test_ids.as_deref().unwrap_or_default();
    if requested_ids.len() > 1 {
        return Err("run one native-discovered test task at a time".into());
    }
    let task = if let Some(test_id) = requested_ids.first() {
        discovered
            .into_iter()
            .find(|task| task.group == "test" && task.id == *test_id)
    } else {
        discovered.into_iter().find(|task| task.group == "test")
    }
    .ok_or_else(|| "no native-discovered test task is available".to_string())?;
    if request
        .command
        .as_ref()
        .is_some_and(|command| command != &task.command)
        || request.args.as_ref().is_some_and(|args| args != &task.args)
    {
        return Err("test definition changed; refresh tests before running it".into());
    }
    let working_directory = task_working_directory(&root, task.cwd.as_deref())?;
    let mut command = command_with_gui_path(&task.command);
    command.current_dir(working_directory).args(&task.args);
    configure_noninteractive_task_environment(&mut command, &task.command);
    let handle = TaskRunHandle::register(&root, &task.id);
    let mut output =
        run_command_output_with_cancellation(command, handle.token()).map_err(to_string)?;
    output.stdout = format!("tests {:?}\n{}", vec![task.id], output.stdout);
    Ok(output)
}

#[tauri::command]
async fn debug_start(
    request: DebugStartRequest,
    manager: tauri::State<'_, DebugAdapterManager>,
) -> Result<DebugSessionResult, String> {
    let manager = manager.inner().clone();
    tauri::async_runtime::spawn_blocking(move || manager.start(request).map_err(to_string))
        .await
        .map_err(|error| format!("debug start worker failed: {error}"))?
}

#[tauri::command]
async fn debug_send(
    request: DebugSendRequest,
    manager: tauri::State<'_, DebugAdapterManager>,
) -> Result<serde_json::Value, String> {
    let manager = manager.inner().clone();
    tauri::async_runtime::spawn_blocking(move || manager.send(request).map_err(to_string))
        .await
        .map_err(|error| format!("debug request worker failed: {error}"))?
}

#[tauri::command]
async fn debug_stop(
    session_id: String,
    manager: tauri::State<'_, DebugAdapterManager>,
) -> Result<serde_json::Value, String> {
    let manager = manager.inner().clone();
    tauri::async_runtime::spawn_blocking(move || manager.stop(&session_id).map_err(to_string))
        .await
        .map_err(|error| format!("debug stop worker failed: {error}"))?
}

impl DebugAdapterManager {
    fn start(&self, request: DebugStartRequest) -> anyhow::Result<DebugSessionResult> {
        let existing_processes = self
            .processes
            .lock()
            .map_err(|_| anyhow::anyhow!("debug adapter manager lock poisoned"))?
            .iter()
            .map(|(session_id, process)| (session_id.clone(), process.clone()))
            .collect::<Vec<_>>();
        let mut stale_processes = Vec::new();
        let mut live_processes = 0usize;
        for (session_id, process) in existing_processes {
            if process
                .lock()
                .map_err(|_| anyhow::anyhow!("debug adapter process lock poisoned"))?
                .child
                .try_wait()?
                .is_some()
            {
                stale_processes.push(session_id);
            } else {
                live_processes += 1;
            }
        }
        if !stale_processes.is_empty() {
            let mut processes = self
                .processes
                .lock()
                .map_err(|_| anyhow::anyhow!("debug adapter manager lock poisoned"))?;
            for session_id in stale_processes {
                processes.remove(&session_id);
            }
        }
        if live_processes >= MAX_DEBUG_ADAPTER_PROCESSES {
            anyhow::bail!("debug adapter process limit reached; stop a debug session first");
        }
        let root = request
            .workspace_path
            .as_deref()
            .map(workspace_root)
            .transpose()?;
        let command_text = request
            .command
            .as_deref()
            .unwrap_or(&request.adapter)
            .trim();
        let mut command_parts = command_text.split_whitespace();
        let command_name = command_parts
            .next()
            .ok_or_else(|| anyhow::anyhow!("debug adapter command is required"))?;
        let mut args = command_parts.map(ToOwned::to_owned).collect::<Vec<_>>();
        args.extend(request.args.clone().unwrap_or_default());
        if !debug_adapter_command_is_allowed(&request.adapter, command_name, &args) {
            anyhow::bail!("debug adapter command requires a native allowlist entry");
        }
        let mut command = command_with_gui_path(command_name);
        command
            .args(args)
            .stdin(Stdio::piped())
            .stdout(Stdio::piped())
            .stderr(Stdio::null());
        if let Some(root) = root.as_ref() {
            command.current_dir(root);
        }
        let mut child = command.spawn().map_err(|error| {
            anyhow::anyhow!("failed to start debug adapter {command_name}: {error}")
        })?;
        let stdin = child
            .stdin
            .take()
            .ok_or_else(|| anyhow::anyhow!("debug adapter stdin unavailable"))?;
        let stdout = child
            .stdout
            .take()
            .ok_or_else(|| anyhow::anyhow!("debug adapter stdout unavailable"))?;
        let mut process = DebugAdapterProcess {
            child,
            stdin,
            messages: spawn_lsp_message_reader(stdout),
            next_sequence: 2,
            name: request.name.clone(),
            adapter: request.adapter.clone(),
        };
        write_lsp_message(
            &mut process.stdin,
            &serde_json::json!({
                "seq": 1,
                "type": "request",
                "command": "initialize",
                "arguments": {
                    "clientID": "gyro",
                    "clientName": "Gyro",
                    "adapterID": request.adapter,
                    "pathFormat": "path",
                    "linesStartAt1": true,
                    "columnsStartAt1": true,
                    "supportsVariableType": true,
                    "supportsVariablePaging": true,
                    "supportsRunInTerminalRequest": false,
                    "supportsMemoryReferences": true,
                    "supportsProgressReporting": true,
                    "supportsInvalidatedEvent": true
                }
            }),
        )?;
        let (response, events) = receive_dap_response(&mut process, 1, Duration::from_secs(12))?;
        if response.get("success").and_then(|value| value.as_bool()) == Some(false) {
            let message = response
                .get("message")
                .and_then(|value| value.as_str())
                .unwrap_or("debug adapter initialize failed");
            anyhow::bail!("{message}");
        }
        let capabilities = response
            .get("body")
            .and_then(|value| value.as_object())
            .map(|body| {
                body.iter()
                    .filter_map(|(key, value)| {
                        value
                            .as_bool()
                            .is_some_and(|value| value)
                            .then_some(key.clone())
                    })
                    .collect::<Vec<_>>()
            })
            .unwrap_or_default();
        let session_id = format!("debug-{}", Uuid::new_v4());
        let message = Some(format!(
            "Initialized with {} capabilities and {} startup events",
            capabilities.len(),
            events.len()
        ));
        let result = DebugSessionResult {
            id: session_id.clone(),
            name: request.name,
            adapter: request.adapter,
            status: "configured".into(),
            message,
            capabilities,
        };
        let mut processes = self
            .processes
            .lock()
            .map_err(|_| anyhow::anyhow!("debug adapter manager lock poisoned"))?;
        if processes.len() >= MAX_DEBUG_ADAPTER_PROCESSES {
            let _ = process.child.kill();
            let _ = process.child.wait();
            anyhow::bail!("debug adapter process limit reached; stop a debug session first");
        }
        processes.insert(session_id, Arc::new(Mutex::new(process)));
        Ok(result)
    }

    fn send(&self, request: DebugSendRequest) -> anyhow::Result<serde_json::Value> {
        let process = self
            .processes
            .lock()
            .map_err(|_| anyhow::anyhow!("debug adapter manager lock poisoned"))?
            .get(&request.session_id)
            .cloned()
            .ok_or_else(|| anyhow::anyhow!("debug session is not running"))?;
        let mut process = process
            .lock()
            .map_err(|_| anyhow::anyhow!("debug adapter process lock poisoned"))?;
        if let Some(status) = process.child.try_wait()? {
            anyhow::bail!("debug adapter exited with {status}");
        }
        let command = request
            .request
            .get("command")
            .and_then(|value| value.as_str())
            .ok_or_else(|| anyhow::anyhow!("debug request command is required"))?;
        if command == "$/gyro/poll" {
            let events = drain_dap_messages(&mut process)?;
            return Ok(redact_json_strings(serde_json::json!({
                "sessionId": request.session_id,
                "name": process.name,
                "adapter": process.adapter,
                "status": "ok",
                "events": events,
            })));
        }
        let sequence = process.next_sequence;
        process.next_sequence += 1;
        write_lsp_message(
            &mut process.stdin,
            &serde_json::json!({
                "seq": sequence,
                "type": "request",
                "command": command,
                "arguments": request.request.get("arguments").cloned().unwrap_or_else(|| serde_json::json!({})),
            }),
        )?;
        let (response, events) =
            receive_dap_response(&mut process, sequence, Duration::from_secs(20))?;
        Ok(redact_json_strings(serde_json::json!({
            "sessionId": request.session_id,
            "status": if response.get("success").and_then(|value| value.as_bool()) == Some(false) { "error" } else { "ok" },
            "response": response,
            "events": events,
        })))
    }

    fn stop(&self, session_id: &str) -> anyhow::Result<serde_json::Value> {
        let process = self
            .processes
            .lock()
            .map_err(|_| anyhow::anyhow!("debug adapter manager lock poisoned"))?
            .remove(session_id);
        let Some(process) = process else {
            return Ok(serde_json::json!({ "sessionId": session_id, "status": "stopped" }));
        };
        let mut process = process
            .lock()
            .map_err(|_| anyhow::anyhow!("debug adapter process lock poisoned"))?;
        let sequence = process.next_sequence;
        let _ = write_lsp_message(
            &mut process.stdin,
            &serde_json::json!({
                "seq": sequence,
                "type": "request",
                "command": "disconnect",
                "arguments": { "terminateDebuggee": false }
            }),
        );
        let _ = receive_dap_response(&mut process, sequence, Duration::from_secs(2));
        let _ = process.child.kill();
        let _ = process.child.wait();
        Ok(serde_json::json!({ "sessionId": session_id, "status": "stopped" }))
    }
}

fn debug_adapter_command_is_allowed(adapter: &str, command: &str, args: &[String]) -> bool {
    if command.is_empty()
        || command.contains('/')
        || command.contains('\\')
        || args.len() > 32
        || args
            .iter()
            .any(|arg| arg.len() > 4_096 || arg.as_bytes().contains(&0))
    {
        return false;
    }
    #[cfg(test)]
    if adapter == "fake" && command == "python3" {
        return true;
    }
    let allowed = [
        "lldb-dap",
        "codelldb",
        "debugpy-adapter",
        "dlv",
        "js-debug-adapter",
        "vscode-js-debug",
        "netcoredbg",
        "OpenDebugAD7",
    ];
    adapter == command && allowed.contains(&command)
}

fn receive_dap_response(
    process: &mut DebugAdapterProcess,
    request_sequence: u64,
    timeout: Duration,
) -> anyhow::Result<(serde_json::Value, Vec<serde_json::Value>)> {
    let deadline = Instant::now() + timeout;
    let mut events = Vec::new();
    let mut event_bytes = 0usize;
    loop {
        let remaining = deadline.saturating_duration_since(Instant::now());
        if remaining.is_zero() {
            anyhow::bail!("debug adapter request timed out");
        }
        let message = process
            .messages
            .recv_timeout(remaining)
            .map_err(|error| anyhow::anyhow!("debug adapter response failed: {error}"))?
            .map_err(anyhow::Error::msg)?;
        if message.get("type").and_then(|value| value.as_str()) == Some("response")
            && message.get("request_seq").and_then(|value| value.as_u64()) == Some(request_sequence)
        {
            return Ok((message, events));
        }
        handle_dap_adapter_request(process, &message)?;
        if events.len() >= MAX_IDE_PROTOCOL_MESSAGES_PER_RESPONSE {
            anyhow::bail!("debug adapter produced too many events before its response");
        }
        add_ide_protocol_message_bytes(&mut event_bytes, &message)?;
        events.push(message);
    }
}

fn drain_dap_messages(process: &mut DebugAdapterProcess) -> anyhow::Result<Vec<serde_json::Value>> {
    let mut messages = Vec::new();
    let mut message_bytes = 0usize;
    for _ in 0..MAX_IDE_PROTOCOL_MESSAGES_PER_RESPONSE {
        let message = match process.messages.try_recv() {
            Ok(message) => message.map_err(anyhow::Error::msg)?,
            Err(mpsc::TryRecvError::Empty) => break,
            Err(mpsc::TryRecvError::Disconnected) => {
                anyhow::bail!("debug adapter output disconnected")
            }
        };
        handle_dap_adapter_request(process, &message)?;
        add_ide_protocol_message_bytes(&mut message_bytes, &message)?;
        messages.push(message);
    }
    Ok(messages)
}

fn add_ide_protocol_message_bytes(
    total: &mut usize,
    message: &serde_json::Value,
) -> anyhow::Result<()> {
    *total = total.saturating_add(serde_json::to_vec(message)?.len());
    if *total > MAX_IDE_PROTOCOL_RESPONSE_BYTES {
        anyhow::bail!("IDE protocol response exceeded its aggregate size limit");
    }
    Ok(())
}

fn handle_dap_adapter_request(
    process: &mut DebugAdapterProcess,
    message: &serde_json::Value,
) -> anyhow::Result<()> {
    if message.get("type").and_then(|value| value.as_str()) != Some("request") {
        return Ok(());
    }
    let Some(request_sequence) = message.get("seq").and_then(|value| value.as_u64()) else {
        return Ok(());
    };
    let command = message
        .get("command")
        .and_then(|value| value.as_str())
        .unwrap_or("adapterRequest");
    let sequence = process.next_sequence;
    process.next_sequence += 1;
    write_lsp_message(
        &mut process.stdin,
        &serde_json::json!({
            "seq": sequence,
            "type": "response",
            "request_seq": request_sequence,
            "command": command,
            "success": false,
            "message": format!("Gyro does not support adapter request {command} yet")
        }),
    )
}

fn redact_json_strings(mut value: serde_json::Value) -> serde_json::Value {
    fn redact(value: &mut serde_json::Value) {
        match value {
            serde_json::Value::String(text) => {
                *text = gyro_core::security::redact_secrets(text);
            }
            serde_json::Value::Array(items) => items.iter_mut().for_each(redact),
            serde_json::Value::Object(map) => map.values_mut().for_each(redact),
            _ => {}
        }
    }
    redact(&mut value);
    value
}

fn read_workspace_file_impl(
    workspace_path: &str,
    path: &str,
) -> anyhow::Result<WorkspaceFileContent> {
    read_workspace_file_with_limit(workspace_path, path, MAX_WORKSPACE_FILE_PREVIEW_BYTES)
}

fn read_workspace_file_with_limit(
    workspace_path: &str,
    path: &str,
    max_bytes: usize,
) -> anyhow::Result<WorkspaceFileContent> {
    let root = PathBuf::from(workspace_path).canonicalize()?;
    let candidate = gyro_core::security::assert_path_inside_workspace(&root, Path::new(path))?;
    let (mut bytes, size_bytes) =
        read_bounded_regular_file(&candidate, max_bytes, "workspace file")?;
    let truncated = bytes.len() > max_bytes;
    if truncated {
        bytes.truncate(max_bytes);
    }
    if bytes.contains(&0) {
        anyhow::bail!("binary workspace files cannot be previewed");
    }
    let content_hash = content_hash(&bytes);
    let content = String::from_utf8_lossy(&bytes).to_string();

    Ok(WorkspaceFileContent {
        path: path.to_string(),
        content,
        truncated,
        size_bytes,
        content_hash,
    })
}

fn read_bounded_regular_file(
    path: &Path,
    max_bytes: usize,
    label: &str,
) -> anyhow::Result<(Vec<u8>, u64)> {
    let mut options = fs::OpenOptions::new();
    options.read(true);
    #[cfg(unix)]
    {
        use std::os::unix::fs::OpenOptionsExt;
        options.custom_flags(libc::O_NOFOLLOW);
    }
    let mut file = options
        .open(path)
        .with_context(|| format!("open {label} {}", path.display()))?;
    let metadata = file.metadata()?;
    if !metadata.is_file() {
        anyhow::bail!("{label} is not a regular file");
    }
    let mut bytes = Vec::with_capacity(max_bytes.min(metadata.len() as usize));
    Read::by_ref(&mut file)
        .take(max_bytes.saturating_add(1) as u64)
        .read_to_end(&mut bytes)
        .with_context(|| format!("read {label} {}", path.display()))?;
    Ok((bytes, metadata.len()))
}

fn stat_workspace_file_impl(workspace_path: &str, path: &str) -> anyhow::Result<WorkspaceFileStat> {
    let root = PathBuf::from(workspace_path).canonicalize()?;
    let candidate = gyro_core::security::assert_path_inside_workspace(&root, Path::new(path))?;
    let metadata = std::fs::metadata(&candidate)?;
    let kind = if metadata.is_dir() {
        "directory"
    } else {
        "file"
    }
    .to_string();
    let content_hash = if metadata.is_file()
        && metadata.len() <= MAX_WORKSPACE_FILE_EDIT_BYTES as u64
    {
        let (bytes, _) =
            read_bounded_regular_file(&candidate, MAX_WORKSPACE_FILE_EDIT_BYTES, "workspace file")?;
        if bytes.len() > MAX_WORKSPACE_FILE_EDIT_BYTES || bytes.contains(&0) {
            None
        } else {
            Some(content_hash(&bytes))
        }
    } else {
        None
    };

    Ok(WorkspaceFileStat {
        path: path.to_string(),
        kind,
        size_bytes: metadata.len(),
        content_hash,
    })
}

fn write_workspace_file_impl(
    request: &WorkspaceFileWriteRequest,
) -> anyhow::Result<WorkspaceFileContent> {
    let root = PathBuf::from(&request.workspace_path).canonicalize()?;
    let candidate = validated_workspace_file_target(&root, &request.path)?;
    if candidate.is_dir() {
        anyhow::bail!("workspace write path is a directory");
    }
    let content_bytes = request.content.as_bytes();
    if content_bytes.len() > MAX_WORKSPACE_FILE_EDIT_BYTES {
        anyhow::bail!("workspace file is too large to edit in Gyro");
    }
    if content_bytes.contains(&0) {
        anyhow::bail!("binary workspace files cannot be edited");
    }
    if let Some(expected_hash) = request.expected_hash.as_deref() {
        let (current, _) =
            read_bounded_regular_file(&candidate, MAX_WORKSPACE_FILE_EDIT_BYTES, "workspace file")?;
        if current.len() > MAX_WORKSPACE_FILE_EDIT_BYTES {
            anyhow::bail!("workspace file is too large to edit in Gyro");
        }
        if current.contains(&0) {
            anyhow::bail!("binary workspace files cannot be edited");
        }
        let current_hash = content_hash(&current);
        if current_hash != expected_hash {
            anyhow::bail!("file changed on disk; reload before saving");
        }
    }

    atomic_write_workspace_file(&candidate, content_bytes)?;
    read_workspace_file_with_limit(
        &request.workspace_path,
        &request.path,
        MAX_WORKSPACE_FILE_EDIT_BYTES,
    )
}

fn create_file_mutation_proposal_impl(
    request: FileMutationProposalRequest,
) -> anyhow::Result<MutationProposal> {
    let store = SessionStore::open(GyroPaths::for_current_user()?)?;
    let session_id = Uuid::parse_str(&request.session_id)?;
    let turn_id = request
        .turn_id
        .as_deref()
        .map(Uuid::parse_str)
        .transpose()?;
    let session = store
        .get_session(session_id)?
        .ok_or_else(|| anyhow::anyhow!("unknown session {session_id}"))?;
    let root = session.workspace_path.canonicalize()?;
    let candidate = validated_workspace_file_target(&root, &request.path)?;
    if candidate.is_dir() {
        anyhow::bail!("mutation proposal path is a directory");
    }
    let content_bytes = request.content.as_bytes();
    if content_bytes.len() > MAX_WORKSPACE_FILE_EDIT_BYTES {
        anyhow::bail!("mutation proposal is too large");
    }
    if content_bytes.contains(&0) {
        anyhow::bail!("binary mutation proposals are not supported");
    }
    let base_exists = candidate.exists();
    let expected_hash = if base_exists {
        let (current, _) =
            read_bounded_regular_file(&candidate, MAX_WORKSPACE_FILE_EDIT_BYTES, "workspace file")?;
        if current.len() > MAX_WORKSPACE_FILE_EDIT_BYTES {
            anyhow::bail!("workspace file is too large to edit in Gyro");
        }
        if current.contains(&0) {
            anyhow::bail!("binary workspace files cannot be edited");
        }
        let current_hash = content_hash(&current);
        if let Some(expected) = request.expected_hash.as_deref() {
            if current_hash != expected {
                anyhow::bail!("file changed on disk; reload before proposing an edit");
            }
        }
        Some(current_hash)
    } else {
        if request.expected_hash.is_some() {
            anyhow::bail!("cannot use an expected hash for a file that does not exist");
        }
        None
    };
    let proposal = store.create_mutation_proposal(
        session_id,
        turn_id,
        &request.path,
        request.content,
        expected_hash,
        base_exists,
    )?;
    let payload = mutation_approval_payload(&proposal, None);
    store.append_event_with_turn_id(
        session_id,
        SessionEventKind::FileEditProposed,
        format!("Proposed {}", proposal.path),
        payload.clone(),
        turn_id,
    )?;
    store.append_event_with_turn_id(
        session_id,
        SessionEventKind::ApprovalRequested,
        format!("Review changes to {}", proposal.path),
        payload,
        turn_id,
    )?;
    let _ = store.mark_mutation_proposal_surfaced(proposal.id);
    Ok(proposal)
}

fn resolve_file_mutation_proposal_impl(
    request: FileMutationDecisionRequest,
) -> anyhow::Result<FileMutationDecisionResult> {
    let store = SessionStore::open(GyroPaths::for_current_user()?)?;
    let proposal_id = Uuid::parse_str(&request.proposal_id)?;
    let decision = match request.decision.as_str() {
        "approve" => MutationDecision::Approve,
        "reject" => MutationDecision::Reject,
        _ => anyhow::bail!("mutation decision must be approve or reject"),
    };
    let result = decide_mutation_proposal(&store, proposal_id, decision)?;
    let file = result
        .changed_path
        .as_ref()
        .map(|_| {
            read_workspace_file_with_limit(
                &result.proposal.workspace_path.to_string_lossy(),
                &result.proposal.path,
                MAX_WORKSPACE_FILE_EDIT_BYTES,
            )
        })
        .transpose()?;
    Ok(FileMutationDecisionResult {
        proposal: result.proposal,
        event: result.event,
        file,
    })
}

fn validated_workspace_file_target(root: &Path, path: &str) -> anyhow::Result<PathBuf> {
    let candidate = gyro_core::security::assert_path_inside_workspace(root, Path::new(path))?;
    let parent = candidate
        .parent()
        .ok_or_else(|| anyhow::anyhow!("workspace file path has no parent"))?;
    let resolved_parent = parent
        .canonicalize()
        .map_err(|_| anyhow::anyhow!("workspace file parent does not exist"))?;
    if !resolved_parent.starts_with(root) {
        anyhow::bail!("workspace file parent resolves outside the workspace");
    }
    Ok(resolved_parent.join(
        candidate
            .file_name()
            .ok_or_else(|| anyhow::anyhow!("workspace file path has no file name"))?,
    ))
}

fn atomic_write_workspace_file(path: &Path, content: &[u8]) -> anyhow::Result<()> {
    let parent = path
        .parent()
        .ok_or_else(|| anyhow::anyhow!("workspace file path has no parent"))?;
    let temporary = parent.join(format!(
        ".gyro-{}-{}.tmp",
        path.file_name()
            .and_then(|name| name.to_str())
            .unwrap_or("mutation"),
        Uuid::new_v4()
    ));
    let result = (|| -> anyhow::Result<()> {
        let mut file = fs::OpenOptions::new()
            .create_new(true)
            .write(true)
            .open(&temporary)?;
        if let Ok(metadata) = fs::metadata(path) {
            file.set_permissions(metadata.permissions())?;
        }
        file.write_all(content)?;
        file.flush()?;
        file.sync_all()?;
        fs::rename(&temporary, path)?;
        fs::File::open(parent)?.sync_all()?;
        Ok(())
    })();
    if result.is_err() {
        let _ = fs::remove_file(&temporary);
    }
    result
}

fn workspace_root(workspace_path: &str) -> anyhow::Result<PathBuf> {
    PathBuf::from(workspace_path)
        .canonicalize()
        .map_err(anyhow::Error::from)
}

fn assert_workspace_path(root: &Path, path: &str) -> anyhow::Result<PathBuf> {
    gyro_core::security::assert_path_inside_workspace(root, Path::new(path))
}

fn create_workspace_path_impl(
    request: &WorkspacePathCreateRequest,
) -> anyhow::Result<WorkspaceFileStat> {
    let root = workspace_root(&request.workspace_path)?;
    let candidate = assert_workspace_path(&root, &request.path)?;
    if candidate.exists() {
        anyhow::bail!("workspace path already exists");
    }
    match request.kind.as_str() {
        "directory" => std::fs::create_dir_all(&candidate)?,
        "file" => {
            if let Some(parent) = candidate.parent() {
                if !parent.starts_with(&root) {
                    anyhow::bail!("workspace file parent is outside workspace");
                }
                std::fs::create_dir_all(parent)?;
            }
            std::fs::OpenOptions::new()
                .write(true)
                .create_new(true)
                .open(&candidate)?;
        }
        _ => anyhow::bail!("workspace path kind must be file or directory"),
    }
    stat_workspace_file_impl(&request.workspace_path, &request.path)
}

fn rename_workspace_path_impl(
    request: &WorkspacePathRenameRequest,
) -> anyhow::Result<WorkspaceFileStat> {
    let root = workspace_root(&request.workspace_path)?;
    let from = assert_workspace_path(&root, &request.from_path)?;
    let to = assert_workspace_path(&root, &request.to_path)?;
    if !from.exists() {
        anyhow::bail!("workspace path does not exist");
    }
    if to.exists() {
        anyhow::bail!("target workspace path already exists");
    }
    if let Some(parent) = to.parent() {
        if !parent.starts_with(&root) {
            anyhow::bail!("target parent is outside workspace");
        }
        std::fs::create_dir_all(parent)?;
    }
    std::fs::rename(from, to)?;
    stat_workspace_file_impl(&request.workspace_path, &request.to_path)
}

fn delete_workspace_path_impl(request: &WorkspacePathDeleteRequest) -> anyhow::Result<bool> {
    let root = workspace_root(&request.workspace_path)?;
    let candidate = assert_workspace_path(&root, &request.path)?;
    if !candidate.exists() {
        anyhow::bail!("workspace path does not exist");
    }
    let metadata = std::fs::metadata(&candidate)?;
    if metadata.is_file() {
        if let Some(expected_hash) = request.expected_hash.as_deref() {
            let (bytes, _) = read_bounded_regular_file(
                &candidate,
                MAX_WORKSPACE_FILE_EDIT_BYTES,
                "workspace file",
            )?;
            if bytes.len() > MAX_WORKSPACE_FILE_EDIT_BYTES {
                anyhow::bail!("workspace file is too large for hash-approved deletion");
            }
            if bytes.contains(&0) {
                anyhow::bail!("binary workspace files cannot be deleted through hash approval");
            }
            let current_hash = content_hash(&bytes);
            if current_hash != expected_hash {
                anyhow::bail!("file changed on disk; reload before deleting");
            }
        }
        std::fs::remove_file(candidate)?;
        return Ok(true);
    }
    std::fs::remove_dir(candidate)?;
    Ok(true)
}

fn search_workspace_impl(
    request: &WorkspaceSearchRequest,
) -> anyhow::Result<Vec<WorkspaceSearchResult>> {
    let root = workspace_root(&request.workspace_path)?;
    let query = request.query.trim();
    if query.is_empty() {
        return Ok(Vec::new());
    }
    let max_results = request.max_results.unwrap_or(200).clamp(1, 1000);
    // Agents (Grok ACP, Claude via capabilities) send regex patterns with `|`
    // and `.*`. Fixed-string mode made those always return zero hits, so the
    // model looped short "I'll investigate" turns and looked like a ~30s stop.
    // UI search keeps fixed-strings so plain typing is not treated as regex.
    let use_regex = request.regex.unwrap_or(false);
    match run_workspace_rg_search(&root, query, request.globs.as_ref(), max_results, use_regex) {
        Ok(results) => Ok(results),
        // Agents sometimes send patterns that are invalid regex. Fall back to a
        // literal search so the capability returns matches instead of an error
        // that short-circuits the whole turn.
        Err(_) if use_regex => {
            run_workspace_rg_search(&root, query, request.globs.as_ref(), max_results, false)
                .or_else(|_| fallback_search_workspace(&root, query, max_results))
        }
        Err(_) => fallback_search_workspace(&root, query, max_results),
    }
}

fn run_workspace_rg_search(
    root: &Path,
    query: &str,
    globs: Option<&Vec<String>>,
    max_results: usize,
    use_regex: bool,
) -> anyhow::Result<Vec<WorkspaceSearchResult>> {
    let mut command = command_with_gui_path("rg");
    command
        .current_dir(root)
        .arg("--line-number")
        .arg("--column")
        .arg("--no-heading")
        .arg("--color")
        .arg("never");
    if !use_regex {
        command.arg("--fixed-strings");
    }
    if let Some(globs) = globs {
        for glob in globs {
            command.arg("--glob").arg(glob);
        }
    }
    command.arg("--").arg(query).arg(".");

    match run_bounded_command(
        &command,
        Duration::from_secs(30),
        Some(Duration::from_secs(10)),
        8 * 1024 * 1024,
        64 * 1024,
    ) {
        Ok(output) if output.succeeded() || output.exit_code() == Some(1) => Ok(parse_rg_output(
            &output.stdout,
            query,
            max_results,
            use_regex,
        )),
        Ok(output) => Err(bounded_command_error("workspace search failed", &output)),
        Err(error) => Err(error),
    }
}

fn parse_rg_output(
    output: &str,
    query: &str,
    max_results: usize,
    use_regex: bool,
) -> Vec<WorkspaceSearchResult> {
    // Fixed-string match length is the query length. For regex, rg's column is
    // the start of the match; without the match end we highlight one character
    // so the range stays valid rather than inventing a length from the pattern.
    let highlight_len = if use_regex {
        1usize
    } else {
        query.chars().count().max(1)
    };
    output
        .lines()
        .filter_map(|line| {
            let mut parts = line.splitn(4, ':');
            let path = parts.next()?.trim_start_matches("./").to_string();
            let line_number = parts.next()?.parse::<usize>().ok()?;
            let start_column = parts.next()?.parse::<usize>().ok()?;
            let text = parts.next().unwrap_or_default().to_string();
            let end_column = start_column + highlight_len;
            Some(WorkspaceSearchResult {
                path,
                line_number,
                line: text,
                ranges: vec![WorkspaceSearchRange {
                    start_column,
                    end_column,
                }],
            })
        })
        .take(max_results)
        .collect()
}

fn fallback_search_workspace(
    root: &Path,
    query: &str,
    max_results: usize,
) -> anyhow::Result<Vec<WorkspaceSearchResult>> {
    let mut results = Vec::new();
    let started_at = Instant::now();
    let mut scanned_files = 0usize;
    let mut scanned_bytes = 0u64;
    for entry in WalkDir::new(root)
        .min_depth(1)
        .max_depth(8)
        .into_iter()
        .filter_entry(|entry| {
            let name = entry.file_name().to_string_lossy();
            !matches!(
                name.as_ref(),
                ".git" | ".next" | "node_modules" | "target" | "dist" | "build"
            )
        })
    {
        if started_at.elapsed() >= WORKSPACE_SEARCH_FALLBACK_TIMEOUT
            || scanned_files >= MAX_WORKSPACE_SEARCH_FALLBACK_FILES
            || scanned_bytes >= MAX_WORKSPACE_SEARCH_FALLBACK_BYTES
        {
            break;
        }
        let entry = entry?;
        if !entry.file_type().is_file() {
            continue;
        }
        let metadata = entry.metadata()?;
        if metadata.len() > MAX_WORKSPACE_FILE_PREVIEW_BYTES as u64 {
            continue;
        }
        if scanned_bytes.saturating_add(metadata.len()) > MAX_WORKSPACE_SEARCH_FALLBACK_BYTES {
            break;
        }
        scanned_files += 1;
        scanned_bytes = scanned_bytes.saturating_add(metadata.len());
        let (bytes, _) = read_bounded_regular_file(
            entry.path(),
            MAX_WORKSPACE_FILE_PREVIEW_BYTES,
            "workspace search file",
        )?;
        if bytes.len() > MAX_WORKSPACE_FILE_PREVIEW_BYTES {
            continue;
        }
        if bytes.contains(&0) {
            continue;
        }
        let content = String::from_utf8_lossy(&bytes);
        for (index, line) in content.lines().enumerate() {
            if let Some(offset) = line.find(query) {
                let path = entry
                    .path()
                    .strip_prefix(root)?
                    .to_string_lossy()
                    .to_string();
                results.push(WorkspaceSearchResult {
                    path,
                    line_number: index + 1,
                    line: line.to_string(),
                    ranges: vec![WorkspaceSearchRange {
                        start_column: offset + 1,
                        end_column: offset + query.len() + 1,
                    }],
                });
                if results.len() >= max_results {
                    return Ok(results);
                }
            }
        }
    }
    Ok(results)
}

fn git_status_impl(workspace_path: &str) -> anyhow::Result<SourceControlStatus> {
    let root = workspace_root(workspace_path)?;
    let mut command = git_command();
    command
        .arg("-C")
        .arg(&root)
        .arg("status")
        .arg("--porcelain=v2")
        .arg("--branch")
        .arg("--untracked-files=all");
    let output = match run_bounded_command(
        &command,
        Duration::from_secs(15),
        Some(Duration::from_secs(10)),
        4 * 1024 * 1024,
        64 * 1024,
    ) {
        Ok(output) => output,
        Err(error) => {
            return Ok(SourceControlStatus {
                provider: "git".into(),
                available: false,
                branch: None,
                upstream: None,
                ahead: 0,
                behind: 0,
                repo_root: None,
                additions: 0,
                deletions: 0,
                stats_partial: false,
                files: Vec::new(),
                last_checked_at: None,
                error: Some(error.to_string()),
            });
        }
    };
    if !output.succeeded() || output.stdout_truncated {
        return Ok(SourceControlStatus {
            provider: "git".into(),
            available: false,
            branch: None,
            upstream: None,
            ahead: 0,
            behind: 0,
            repo_root: None,
            additions: 0,
            deletions: 0,
            stats_partial: false,
            files: Vec::new(),
            last_checked_at: None,
            error: Some(bounded_command_error("could not inspect Git status", &output).to_string()),
        });
    }
    let mut status = parse_git_status_v2(&output.stdout);
    let repo_root = git_repo_root(&root).unwrap_or(root);
    apply_git_diff_stats(&repo_root, &mut status);
    status.repo_root = Some(repo_root.display().to_string());
    status.last_checked_at = Some(chrono::Utc::now().to_rfc3339());
    Ok(status)
}

fn parse_git_status_v2(output: &str) -> SourceControlStatus {
    let mut status = SourceControlStatus {
        provider: "git".into(),
        available: true,
        branch: None,
        upstream: None,
        ahead: 0,
        behind: 0,
        repo_root: None,
        additions: 0,
        deletions: 0,
        stats_partial: false,
        files: Vec::new(),
        last_checked_at: None,
        error: None,
    };

    for line in output.lines() {
        if let Some(branch) = line.strip_prefix("# branch.head ") {
            status.branch = Some(branch.to_string());
        } else if let Some(upstream) = line.strip_prefix("# branch.upstream ") {
            status.upstream = Some(upstream.to_string());
        } else if let Some(ab) = line.strip_prefix("# branch.ab ") {
            for part in ab.split_whitespace() {
                if let Some(value) = part.strip_prefix('+') {
                    status.ahead = value.parse().unwrap_or(0);
                } else if let Some(value) = part.strip_prefix('-') {
                    status.behind = value.parse().unwrap_or(0);
                }
            }
        } else if let Some(path) = line.strip_prefix("? ") {
            status.files.push(SourceControlFile {
                path: path.to_string(),
                original_path: None,
                state: "untracked".into(),
                staged: false,
                additions: 0,
                deletions: 0,
            });
        } else if line.starts_with("1 ") {
            let mut parts = line.split_whitespace();
            let _record = parts.next();
            let xy = parts.next().unwrap_or("..");
            let path = parts.nth(6).unwrap_or_default().to_string();
            push_git_status_sides(&mut status.files, xy, path, None);
        } else if line.starts_with("2 ") {
            let mut parts = line.split_whitespace();
            let _record = parts.next();
            let xy = parts.next().unwrap_or("..");
            let _sub = parts.next();
            (0..5).for_each(|_| {
                let _ = parts.next();
            });
            let _score = parts.next();
            let rest = parts.collect::<Vec<_>>().join(" ");
            let mut paths = rest.split('\t');
            let path = paths.next().unwrap_or_default().to_string();
            let original_path = paths.next().map(ToOwned::to_owned);
            push_git_status_sides(&mut status.files, xy, path, original_path);
        } else if line.starts_with("u ") {
            let path = line
                .split_whitespace()
                .last()
                .unwrap_or_default()
                .to_string();
            status.files.push(SourceControlFile {
                path,
                original_path: None,
                state: "conflicted".into(),
                staged: false,
                additions: 0,
                deletions: 0,
            });
        }
    }
    status
}

fn git_repo_root(workspace: &Path) -> Option<PathBuf> {
    let mut command = git_command();
    command
        .arg("-C")
        .arg(workspace)
        .args(["rev-parse", "--show-toplevel"]);
    let output = run_bounded_command(
        &command,
        Duration::from_secs(10),
        None,
        64 * 1024,
        64 * 1024,
    )
    .ok()?;
    if !output.succeeded() || output.stdout_truncated {
        return None;
    }
    let path = output.stdout.trim().to_string();
    (!path.is_empty()).then(|| PathBuf::from(path))
}

fn apply_git_diff_stats(repo_root: &Path, status: &mut SourceControlStatus) {
    let (tracked, tracked_partial) = git_numstat(repo_root);
    status.stats_partial = tracked_partial;

    for (additions, deletions) in tracked.values() {
        status.additions = status.additions.saturating_add(*additions);
        status.deletions = status.deletions.saturating_add(*deletions);
    }

    let untracked_started_at = Instant::now();
    let mut untracked_files = 0usize;
    let mut untracked_bytes = 0usize;
    for file in &mut status.files {
        if let Some((additions, deletions)) = tracked.get(&file.path).or_else(|| {
            file.original_path
                .as_ref()
                .and_then(|path| tracked.get(path))
        }) {
            file.additions = *additions;
            file.deletions = *deletions;
        }
        if file.state == "untracked" {
            if untracked_files >= MAX_GIT_UNTRACKED_STAT_FILES
                || untracked_bytes >= MAX_GIT_UNTRACKED_STAT_BYTES
                || untracked_started_at.elapsed() >= GIT_UNTRACKED_STAT_TIMEOUT
            {
                status.stats_partial = true;
                continue;
            }
            let (additions, partial, bytes_read) = untracked_text_additions(
                repo_root,
                &file.path,
                MAX_GIT_UNTRACKED_STAT_BYTES - untracked_bytes,
            );
            untracked_files += 1;
            untracked_bytes = untracked_bytes.saturating_add(bytes_read);
            file.additions = additions;
            status.additions = status.additions.saturating_add(additions);
            status.stats_partial |= partial;
        }
    }
}

fn git_numstat(repo_root: &Path) -> (HashMap<String, (usize, usize)>, bool) {
    let mut command = git_command();
    command
        .arg("-C")
        .arg(repo_root)
        .args(["diff", "--numstat", "--no-renames", "HEAD", "--"]);
    let output = match run_bounded_command(
        &command,
        Duration::from_secs(15),
        Some(Duration::from_secs(10)),
        4 * 1024 * 1024,
        64 * 1024,
    ) {
        Ok(output) if output.succeeded() => output,
        _ => return git_numstat_without_head(repo_root),
    };
    let (stats, partial) = parse_git_numstat(&output.stdout);
    (stats, partial || output.stdout_truncated)
}

fn git_numstat_without_head(repo_root: &Path) -> (HashMap<String, (usize, usize)>, bool) {
    let mut totals = HashMap::new();
    let mut partial = false;
    for args in [
        &["diff", "--numstat", "--no-renames", "--cached", "--"][..],
        &["diff", "--numstat", "--no-renames", "--"][..],
    ] {
        let mut command = git_command();
        command.arg("-C").arg(repo_root).args(args);
        let Ok(output) = run_bounded_command(
            &command,
            Duration::from_secs(15),
            Some(Duration::from_secs(10)),
            4 * 1024 * 1024,
            64 * 1024,
        ) else {
            partial = true;
            continue;
        };
        if !output.succeeded() {
            partial = true;
            continue;
        }
        let (stats, output_partial) = parse_git_numstat(&output.stdout);
        partial |= output_partial || output.stdout_truncated;
        for (path, (additions, deletions)) in stats {
            let entry = totals.entry(path).or_insert((0usize, 0usize));
            entry.0 = entry.0.saturating_add(additions);
            entry.1 = entry.1.saturating_add(deletions);
        }
    }
    (totals, partial)
}

fn parse_git_numstat(output: &str) -> (HashMap<String, (usize, usize)>, bool) {
    let mut totals = HashMap::new();
    let mut partial = false;
    for line in output.lines() {
        let mut parts = line.splitn(3, '\t');
        let additions = parts.next().unwrap_or_default();
        let deletions = parts.next().unwrap_or_default();
        let path = parts.next().unwrap_or_default();
        if path.is_empty() {
            continue;
        }
        let (Ok(additions), Ok(deletions)) = (additions.parse(), deletions.parse()) else {
            partial = true;
            continue;
        };
        totals.insert(path.to_string(), (additions, deletions));
    }
    (totals, partial)
}

fn untracked_text_additions(
    repo_root: &Path,
    relative_path: &str,
    remaining_bytes: usize,
) -> (usize, bool, usize) {
    let path = repo_root.join(relative_path);
    let Ok(metadata) = fs::metadata(&path) else {
        return (0, true, 0);
    };
    let max_bytes = MAX_WORKSPACE_FILE_EDIT_BYTES.min(remaining_bytes);
    if !metadata.is_file() || metadata.len() > max_bytes as u64 {
        return (0, metadata.is_file(), 0);
    }
    let Ok((bytes, _)) = read_bounded_regular_file(&path, max_bytes, "untracked workspace file")
    else {
        return (0, true, 0);
    };
    if bytes.len() > max_bytes {
        return (0, true, 0);
    }
    if bytes.contains(&0) {
        return (0, false, bytes.len());
    }
    let lines = bytes.iter().filter(|byte| **byte == b'\n').count()
        + usize::from(!bytes.is_empty() && bytes.last() != Some(&b'\n'));
    (lines, false, bytes.len())
}

/// Porcelain v2 reports two statuses per file: X for the index and Y for the
/// working tree. A file can carry both — staged edits plus newer unstaged ones
/// — so each side becomes its own row, which is how VS Code lists the file
/// under both "Staged Changes" and "Changes".
fn push_git_status_sides(
    files: &mut Vec<SourceControlFile>,
    xy: &str,
    path: String,
    original_path: Option<String>,
) {
    let mut codes = xy.chars();
    let index = codes.next().unwrap_or('.');
    let worktree = codes.next().unwrap_or('.');
    if index != '.' {
        files.push(SourceControlFile {
            path: path.clone(),
            original_path: original_path.clone(),
            state: git_state_from_code(index),
            staged: true,
            additions: 0,
            deletions: 0,
        });
    }
    if worktree != '.' || index == '.' {
        files.push(SourceControlFile {
            path,
            original_path,
            state: git_state_from_code(worktree),
            staged: false,
            additions: 0,
            deletions: 0,
        });
    }
}

fn git_state_from_code(code: char) -> String {
    match code {
        'D' => "deleted",
        'A' => "added",
        'R' | 'C' => "renamed",
        'U' => "conflicted",
        _ => "modified",
    }
    .into()
}

const MAX_CUSTOM_WORKSPACE_TASKS: usize = 64;
const MAX_DISCOVERED_TASKS: usize = 240;
const MAX_CUSTOM_TASK_FILE_BYTES: usize = 128 * 1024;
const MAX_MANIFEST_SCAN_BYTES: usize = 512 * 1024;
const MAX_TARGETS_PER_MANIFEST: usize = 40;
const MAX_CUSTOM_TASK_LABEL_CHARS: usize = 80;
const MAX_CUSTOM_TASK_TOKEN_CHARS: usize = 400;
const MAX_CUSTOM_TASK_ARGS: usize = 48;

fn default_custom_task_group() -> String {
    "custom".into()
}

fn task_group_for_name(name: &str) -> &'static str {
    let name = name.to_ascii_lowercase();
    if name.contains("test") || name.contains("spec") || name.contains("check") {
        "test"
    } else if name.contains("build") || name.contains("compile") || name.contains("bundle") {
        "build"
    } else if name.contains("dev") || name.contains("start") || name.contains("serve") {
        "dev"
    } else {
        "custom"
    }
}

fn task_id_slug(value: &str) -> String {
    let mut slug = String::new();
    for character in value.chars() {
        if character.is_ascii_alphanumeric() || matches!(character, '-' | '_' | '.' | '/' | ':') {
            slug.push(character);
        } else if !slug.ends_with('-') {
            slug.push('-');
        }
    }
    slug.trim_matches('-').to_string()
}

fn suggested_task(
    id: String,
    label: String,
    command: &str,
    args: Vec<String>,
    group: &str,
) -> TaskDefinitionResult {
    let channel = format!("task-{}", task_id_slug(&id).replace([':', '/'], "-"));
    TaskDefinitionResult {
        id,
        label,
        command: command.into(),
        args,
        group: group.into(),
        cwd: None,
        status: "idle".into(),
        output_channel_id: Some(channel),
        source: "suggested".into(),
    }
}

fn read_manifest_text(path: &Path, label: &str) -> Option<String> {
    let (bytes, _) = read_bounded_regular_file(path, MAX_MANIFEST_SCAN_BYTES, label).ok()?;
    if bytes.len() > MAX_MANIFEST_SCAN_BYTES {
        return None;
    }
    String::from_utf8(bytes).ok()
}

fn node_script_runner(root: &Path) -> &'static str {
    if root.join("pnpm-lock.yaml").exists() {
        "pnpm"
    } else if root.join("bun.lockb").exists() || root.join("bun.lock").exists() {
        "bun"
    } else if root.join("yarn.lock").exists() {
        "yarn"
    } else {
        "npm"
    }
}

fn discover_package_script_tasks(
    root: &Path,
    tasks: &mut Vec<TaskDefinitionResult>,
) -> anyhow::Result<()> {
    let package_json = root.join("package.json");
    if !package_json.exists() {
        return Ok(());
    }
    let (package, _) = read_bounded_regular_file(&package_json, 1024 * 1024, "package manifest")?;
    if package.len() > 1024 * 1024 {
        anyhow::bail!("package manifest exceeds the 1 MiB size limit");
    }
    let package = String::from_utf8(package).context("package manifest is not UTF-8")?;
    let Ok(value) = serde_json::from_str::<serde_json::Value>(&package) else {
        return Ok(());
    };
    let Some(scripts) = value.get("scripts").and_then(|value| value.as_object()) else {
        return Ok(());
    };
    let runner = node_script_runner(root);
    for name in scripts.keys().take(MAX_TARGETS_PER_MANIFEST) {
        tasks.push(suggested_task(
            format!("package:{name}"),
            format!("{runner} {name}"),
            runner,
            vec!["run".into(), name.to_string()],
            task_group_for_name(name),
        ));
    }
    Ok(())
}

fn discover_cargo_tasks(root: &Path, tasks: &mut Vec<TaskDefinitionResult>) {
    if !root.join("Cargo.toml").exists() {
        return;
    }
    for (name, args, group) in [
        ("build", vec!["build"], "build"),
        ("test", vec!["test"], "test"),
        ("check", vec!["check"], "build"),
        ("clippy", vec!["clippy", "--all-targets"], "test"),
        ("fmt", vec!["fmt", "--check"], "custom"),
    ] {
        tasks.push(suggested_task(
            format!("cargo:{name}"),
            format!("cargo {}", args.join(" ")),
            "cargo",
            args.into_iter().map(str::to_string).collect(),
            group,
        ));
    }
}

/// Reads plain `target:` rules out of a Makefile, skipping pattern rules,
/// variable assignments, and recipe bodies.
fn makefile_targets(source: &str) -> Vec<String> {
    let mut targets = Vec::new();
    let mut seen = HashSet::new();
    for line in source.lines() {
        if line.starts_with([' ', '\t']) || line.trim_start().starts_with('#') {
            continue;
        }
        let Some(colon) = line.find(':') else {
            continue;
        };
        if line[colon..].starts_with(":=") {
            continue;
        }
        let head = line[..colon].trim();
        if head.is_empty() || head.starts_with('.') || head.contains(['%', '$', '=', '(', ')', '"'])
        {
            continue;
        }
        for target in head.split_whitespace() {
            if !target
                .chars()
                .all(|character| character.is_ascii_alphanumeric() || "-_./".contains(character))
            {
                continue;
            }
            if seen.insert(target.to_string()) {
                targets.push(target.to_string());
            }
        }
        if targets.len() >= MAX_TARGETS_PER_MANIFEST {
            break;
        }
    }
    targets.truncate(MAX_TARGETS_PER_MANIFEST);
    targets
}

fn discover_makefile_tasks(root: &Path, tasks: &mut Vec<TaskDefinitionResult>) {
    let Some(makefile) = ["Makefile", "makefile", "GNUmakefile"]
        .into_iter()
        .map(|name| root.join(name))
        .find(|path| path.is_file())
    else {
        return;
    };
    let Some(source) = read_manifest_text(&makefile, "makefile") else {
        return;
    };
    for target in makefile_targets(&source) {
        tasks.push(suggested_task(
            format!("make:{target}"),
            format!("make {target}"),
            "make",
            vec![target.clone()],
            task_group_for_name(&target),
        ));
    }
}

/// Reads recipe names out of a justfile, skipping assignments and settings.
fn justfile_recipes(source: &str) -> Vec<String> {
    let mut recipes = Vec::new();
    let mut seen = HashSet::new();
    for line in source.lines() {
        if line.starts_with([' ', '\t']) || line.trim_start().starts_with('#') {
            continue;
        }
        let trimmed = line.trim_start_matches('@').trim();
        let Some(colon) = trimmed.find(':') else {
            continue;
        };
        if trimmed[colon..].starts_with(":=") {
            continue;
        }
        let head = trimmed[..colon].trim();
        let Some(name) = head.split_whitespace().next() else {
            continue;
        };
        if matches!(name, "set" | "export" | "alias" | "import" | "mod") {
            continue;
        }
        if !name
            .chars()
            .all(|character| character.is_ascii_alphanumeric() || "-_".contains(character))
        {
            continue;
        }
        if seen.insert(name.to_string()) {
            recipes.push(name.to_string());
        }
        if recipes.len() >= MAX_TARGETS_PER_MANIFEST {
            break;
        }
    }
    recipes
}

fn discover_justfile_tasks(root: &Path, tasks: &mut Vec<TaskDefinitionResult>) {
    let Some(justfile) = ["justfile", "Justfile", ".justfile"]
        .into_iter()
        .map(|name| root.join(name))
        .find(|path| path.is_file())
    else {
        return;
    };
    let Some(source) = read_manifest_text(&justfile, "justfile") else {
        return;
    };
    for recipe in justfile_recipes(&source) {
        tasks.push(suggested_task(
            format!("just:{recipe}"),
            format!("just {recipe}"),
            "just",
            vec![recipe.clone()],
            task_group_for_name(&recipe),
        ));
    }
}

fn discover_python_tasks(root: &Path, tasks: &mut Vec<TaskDefinitionResult>) {
    let pyproject = root.join("pyproject.toml");
    let has_project = pyproject.exists()
        || root.join("setup.py").exists()
        || root.join("pytest.ini").exists()
        || root.join("tox.ini").exists();
    if !has_project {
        return;
    }
    let uses_uv = root.join("uv.lock").exists();
    let uses_poetry = read_manifest_text(&pyproject, "python manifest")
        .is_some_and(|source| source.contains("[tool.poetry"));
    let (command, prefix) = if uses_uv {
        ("uv", vec!["run".to_string()])
    } else if uses_poetry {
        ("poetry", vec!["run".to_string()])
    } else {
        ("python3", vec!["-m".to_string()])
    };
    let mut pytest_args = prefix.clone();
    pytest_args.push("pytest".into());
    tasks.push(suggested_task(
        "python:pytest".into(),
        format!("{command} {}", pytest_args.join(" ")),
        command,
        pytest_args,
        "test",
    ));
    if root.join("ruff.toml").exists()
        || read_manifest_text(&pyproject, "python manifest")
            .is_some_and(|source| source.contains("[tool.ruff"))
    {
        let mut ruff_args = prefix;
        ruff_args.push("ruff".into());
        ruff_args.push("check".into());
        tasks.push(suggested_task(
            "python:ruff".into(),
            format!("{command} {}", ruff_args.join(" ")),
            command,
            ruff_args,
            "custom",
        ));
    }
}

fn discover_go_tasks(root: &Path, tasks: &mut Vec<TaskDefinitionResult>) {
    if !root.join("go.mod").exists() {
        return;
    }
    for (name, args, group) in [
        ("build", vec!["build", "./..."], "build"),
        ("test", vec!["test", "./..."], "test"),
        ("vet", vec!["vet", "./..."], "custom"),
    ] {
        tasks.push(suggested_task(
            format!("go:{name}"),
            format!("go {}", args.join(" ")),
            "go",
            args.into_iter().map(str::to_string).collect(),
            group,
        ));
    }
}

fn discover_deno_tasks(root: &Path, tasks: &mut Vec<TaskDefinitionResult>) {
    let deno_json = root.join("deno.json");
    if !deno_json.is_file() {
        return;
    }
    let Some(source) = read_manifest_text(&deno_json, "deno manifest") else {
        return;
    };
    let Ok(value) = serde_json::from_str::<serde_json::Value>(&source) else {
        return;
    };
    let Some(entries) = value.get("tasks").and_then(|value| value.as_object()) else {
        return;
    };
    for name in entries.keys().take(MAX_TARGETS_PER_MANIFEST) {
        tasks.push(suggested_task(
            format!("deno:{name}"),
            format!("deno task {name}"),
            "deno",
            vec!["task".into(), name.to_string()],
            task_group_for_name(name),
        ));
    }
}

fn custom_tasks_path(root: &Path) -> PathBuf {
    root.join(".gyro").join("tasks.json")
}

fn read_custom_tasks(root: &Path) -> anyhow::Result<Vec<CustomTaskRecord>> {
    let path = custom_tasks_path(root);
    if !path.exists() {
        return Ok(Vec::new());
    }
    let (bytes, _) =
        read_bounded_regular_file(&path, MAX_CUSTOM_TASK_FILE_BYTES, "saved commands")?;
    if bytes.len() > MAX_CUSTOM_TASK_FILE_BYTES {
        anyhow::bail!("saved commands file exceeds the 128 KiB size limit");
    }
    let text = String::from_utf8(bytes).context("saved commands file is not UTF-8")?;
    let file: CustomTaskFile =
        serde_json::from_str(&text).context("saved commands file is not valid JSON")?;
    Ok(file
        .tasks
        .into_iter()
        .filter(|task| {
            !task.id.trim().is_empty()
                && !task.command.trim().is_empty()
                && task.args.len() <= MAX_CUSTOM_TASK_ARGS
        })
        .take(MAX_CUSTOM_WORKSPACE_TASKS)
        .collect())
}

fn write_custom_tasks(root: &Path, tasks: &[CustomTaskRecord]) -> anyhow::Result<()> {
    let path = custom_tasks_path(root);
    if let Some(parent) = path.parent() {
        fs::create_dir_all(parent).context("create the .gyro directory")?;
    }
    let mut body = serde_json::to_vec_pretty(&CustomTaskFile {
        version: 1,
        tasks: tasks.to_vec(),
    })?;
    body.push(b'\n');
    atomic_write_workspace_file(&path, &body)
}

fn custom_task_definition(record: &CustomTaskRecord) -> TaskDefinitionResult {
    TaskDefinitionResult {
        id: record.id.clone(),
        label: record.label.clone(),
        command: record.command.clone(),
        args: record.args.clone(),
        group: record.group.clone(),
        cwd: record.cwd.clone(),
        status: "idle".into(),
        output_channel_id: Some(format!(
            "task-{}",
            task_id_slug(&record.id).replace([':', '/'], "-")
        )),
        source: "custom".into(),
    }
}

/// Splits a typed command line into a program and arguments without a shell,
/// honouring single quotes, double quotes, and backslash escapes.
fn parse_command_line(input: &str) -> anyhow::Result<(String, Vec<String>)> {
    let mut tokens: Vec<String> = Vec::new();
    let mut current = String::new();
    let mut open = false;
    let mut quote: Option<char> = None;
    let mut characters = input.chars();
    while let Some(character) = characters.next() {
        match quote {
            Some(active) => {
                if character == active {
                    quote = None;
                } else if character == '\\' && active == '"' {
                    let escaped = characters
                        .next()
                        .ok_or_else(|| anyhow::anyhow!("command ends with a dangling escape"))?;
                    current.push(escaped);
                } else {
                    current.push(character);
                }
            }
            None => match character {
                '\'' | '"' => {
                    quote = Some(character);
                    open = true;
                }
                '\\' => {
                    let escaped = characters
                        .next()
                        .ok_or_else(|| anyhow::anyhow!("command ends with a dangling escape"))?;
                    current.push(escaped);
                    open = true;
                }
                whitespace if whitespace.is_whitespace() => {
                    if open {
                        tokens.push(std::mem::take(&mut current));
                        open = false;
                    }
                }
                other => {
                    current.push(other);
                    open = true;
                }
            },
        }
    }
    if quote.is_some() {
        anyhow::bail!("command has an unclosed quote");
    }
    if open {
        tokens.push(current);
    }
    let mut tokens = tokens.into_iter();
    let command = tokens
        .next()
        .ok_or_else(|| anyhow::anyhow!("enter a command to run"))?;
    let args: Vec<String> = tokens.collect();
    if command.chars().count() > MAX_CUSTOM_TASK_TOKEN_CHARS
        || args
            .iter()
            .any(|arg| arg.chars().count() > MAX_CUSTOM_TASK_TOKEN_CHARS)
    {
        anyhow::bail!("command parts must stay under {MAX_CUSTOM_TASK_TOKEN_CHARS} characters");
    }
    if args.len() > MAX_CUSTOM_TASK_ARGS {
        anyhow::bail!("commands are limited to {MAX_CUSTOM_TASK_ARGS} arguments");
    }
    if command.contains('\0') || args.iter().any(|arg| arg.contains('\0')) {
        anyhow::bail!("command contains an invalid character");
    }
    Ok((command, args))
}

fn normalize_custom_task_group(group: Option<&str>) -> String {
    match group.map(str::trim) {
        Some("build") => "build".into(),
        Some("test") => "test".into(),
        Some("dev") => "dev".into(),
        _ => default_custom_task_group(),
    }
}

fn unique_custom_task_id(base: &str, existing: &[CustomTaskRecord]) -> String {
    let slug = {
        let slug = task_id_slug(base).replace([':', '/'], "-");
        if slug.is_empty() {
            "command".to_string()
        } else {
            slug.chars().take(48).collect::<String>()
        }
    };
    let mut candidate = format!("custom:{slug}");
    let mut suffix = 2;
    while existing.iter().any(|task| task.id == candidate) {
        candidate = format!("custom:{slug}-{suffix}");
        suffix += 1;
    }
    candidate
}

fn custom_task_create_impl(
    request: &CustomTaskCreateRequest,
) -> anyhow::Result<Vec<TaskDefinitionResult>> {
    let root = workspace_root(&request.workspace_path)?;
    let (command, args) = parse_command_line(&request.command_line)?;
    let mut existing = read_custom_tasks(&root)?;
    if existing.len() >= MAX_CUSTOM_WORKSPACE_TASKS {
        anyhow::bail!("this workspace already has {MAX_CUSTOM_WORKSPACE_TASKS} saved commands");
    }
    let command_line = if args.is_empty() {
        command.clone()
    } else {
        format!("{command} {}", args.join(" "))
    };
    let label = request
        .label
        .as_deref()
        .map(str::trim)
        .filter(|label| !label.is_empty())
        .unwrap_or(command_line.as_str())
        .chars()
        .take(MAX_CUSTOM_TASK_LABEL_CHARS)
        .collect::<String>();
    let cwd = match request.cwd.as_deref().map(str::trim) {
        Some(relative) if !relative.is_empty() => {
            let resolved = assert_workspace_path(&root, relative)?;
            if !resolved.is_dir() {
                anyhow::bail!("working directory does not exist in this workspace");
            }
            Some(relative.to_string())
        }
        _ => None,
    };
    let record = CustomTaskRecord {
        id: unique_custom_task_id(&label, &existing),
        label,
        command,
        args,
        group: normalize_custom_task_group(request.group.as_deref()),
        cwd,
    };
    existing.push(record);
    write_custom_tasks(&root, &existing)?;
    task_discover_impl(&request.workspace_path)
}

fn custom_task_delete_impl(
    request: &CustomTaskDeleteRequest,
) -> anyhow::Result<Vec<TaskDefinitionResult>> {
    let root = workspace_root(&request.workspace_path)?;
    let existing = read_custom_tasks(&root)?;
    let retained: Vec<CustomTaskRecord> = existing
        .iter()
        .filter(|task| task.id != request.task_id)
        .cloned()
        .collect();
    if retained.len() != existing.len() {
        write_custom_tasks(&root, &retained)?;
    }
    task_discover_impl(&request.workspace_path)
}

fn task_discover_impl(workspace_path: &str) -> anyhow::Result<Vec<TaskDefinitionResult>> {
    let root = workspace_root(workspace_path)?;
    let mut tasks: Vec<TaskDefinitionResult> = read_custom_tasks(&root)
        .unwrap_or_default()
        .iter()
        .map(custom_task_definition)
        .collect();
    discover_package_script_tasks(&root, &mut tasks)?;
    discover_cargo_tasks(&root, &mut tasks);
    discover_makefile_tasks(&root, &mut tasks);
    discover_justfile_tasks(&root, &mut tasks);
    discover_python_tasks(&root, &mut tasks);
    discover_go_tasks(&root, &mut tasks);
    discover_deno_tasks(&root, &mut tasks);
    let mut seen = HashSet::new();
    tasks.retain(|task| seen.insert(task.id.clone()));
    tasks.truncate(MAX_DISCOVERED_TASKS);
    Ok(tasks)
}

fn test_discover_impl(workspace_path: &str) -> anyhow::Result<Vec<TestTreeItemResult>> {
    let tasks = task_discover_impl(workspace_path)?;
    Ok(test_tree_from_tasks(&tasks))
}

fn test_tree_from_tasks(tasks: &[TaskDefinitionResult]) -> Vec<TestTreeItemResult> {
    let children = tasks
        .iter()
        .filter(|task| task.group == "test")
        .map(|task| TestTreeItemResult {
            id: task.id.clone(),
            label: task.label.clone(),
            path: None,
            status: "unknown".into(),
            children: Vec::new(),
        })
        .collect::<Vec<_>>();
    vec![TestTreeItemResult {
        id: "workspace-tests".into(),
        label: "Workspace tests".into(),
        path: None,
        status: "unknown".into(),
        children,
    }]
}

fn run_command_output(command: Command) -> anyhow::Result<IdeCommandOutput> {
    run_command_output_with_cancellation(command, CancellationToken::default())
}

fn run_command_output_with_cancellation(
    command: Command,
    cancellation: CancellationToken,
) -> anyhow::Result<IdeCommandOutput> {
    let output = run_bounded_command_with_cancellation(
        &command,
        Duration::from_secs(30 * 60),
        Some(Duration::from_secs(5 * 60)),
        2 * 1024 * 1024,
        1024 * 1024,
        cancellation,
    )?;
    let mut stdout = gyro_core::security::redact_secrets(&output.stdout);
    let mut stderr = gyro_core::security::redact_secrets(&output.stderr);
    if output.stdout_truncated {
        stdout.push_str("\n[stdout truncated by Gyro]");
    }
    if output.stderr_truncated {
        stderr.push_str("\n[stderr truncated by Gyro]");
    }
    Ok(IdeCommandOutput {
        status: match output.termination {
            ExecutionTermination::Exited { code: Some(0) } => "done",
            ExecutionTermination::Cancelled => "cancelled",
            ExecutionTermination::TimedOut => "timed-out",
            ExecutionTermination::Inactive => "inactive",
            ExecutionTermination::OutputLimit => "output-limit",
            ExecutionTermination::Exited { .. } => "failed",
        }
        .into(),
        stdout,
        stderr,
    })
}

fn run_bounded_command(
    command: &Command,
    timeout: Duration,
    inactivity_timeout: Option<Duration>,
    max_stdout_chars: usize,
    max_stderr_chars: usize,
) -> anyhow::Result<gyro_core::ExecutionOutcome> {
    run_bounded_command_with_cancellation(
        command,
        timeout,
        inactivity_timeout,
        max_stdout_chars,
        max_stderr_chars,
        CancellationToken::default(),
    )
}

fn run_bounded_command_with_cancellation(
    command: &Command,
    timeout: Duration,
    inactivity_timeout: Option<Duration>,
    max_stdout_chars: usize,
    max_stderr_chars: usize,
    cancellation: CancellationToken,
) -> anyhow::Result<gyro_core::ExecutionOutcome> {
    let mut request = ExecutionRequest::new(command.get_program().to_os_string());
    request.args = command
        .get_args()
        .map(std::ffi::OsStr::to_os_string)
        .collect();
    request.current_dir = command.get_current_dir().map(Path::to_path_buf);
    request.env = command
        .get_envs()
        .map(|(key, value)| (key.to_os_string(), value.map(std::ffi::OsStr::to_os_string)))
        .collect();
    request.timeout = timeout;
    request.inactivity_timeout = inactivity_timeout;
    request.max_stdout_chars = max_stdout_chars;
    request.max_stderr_chars = max_stderr_chars;
    gyro_core::run_command(request, cancellation, |_| {})
}

fn bounded_command_error(label: &str, output: &gyro_core::ExecutionOutcome) -> anyhow::Error {
    let reason = match &output.termination {
        ExecutionTermination::Exited { code } => format!("exited with {code:?}"),
        ExecutionTermination::Cancelled => "was cancelled".into(),
        ExecutionTermination::TimedOut => "timed out".into(),
        ExecutionTermination::Inactive => "stopped after no output".into(),
        ExecutionTermination::OutputLimit => "exceeded its output limit".into(),
    };
    let detail = output.stderr.trim();
    if detail.is_empty() {
        anyhow::anyhow!("{label} {reason}")
    } else {
        anyhow::anyhow!("{label} {reason}: {}", truncate_error_detail(detail))
    }
}

fn content_hash(bytes: &[u8]) -> String {
    let digest = Sha256::digest(bytes);
    digest.iter().map(|byte| format!("{byte:02x}")).collect()
}

#[tauri::command]
async fn create_terminal_pane(
    app: tauri::AppHandle,
    manager: tauri::State<'_, TerminalProcessManager>,
    mut request: TerminalPaneRequest,
) -> Result<TerminalPaneSnapshot, String> {
    // Governance is resolved here, never taken from the renderer, so the
    // session identity and approval environment an agent CLI inherits always
    // come from persisted backend state.
    request.governance = None;
    if request.governed {
        request.governance = Some(resolve_pane_governance(&app, &request).map_err(to_string)?);
    }
    let governed_session = request
        .governance
        .as_ref()
        .map(|governance| governance.session_id.clone());
    // Relaunching into an occupied pane id replaces that process, so retire the
    // approval authority it held rather than leaving a dead pane able to
    // approve. `restart` deliberately does not come through here: it reuses the
    // same governance so a restarted pane keeps its session identity.
    let displaced = manager.governed_session(&request.pane_id);
    let manager = manager.inner().clone();
    let result =
        tauri::async_runtime::spawn_blocking(move || manager.create(request).map_err(to_string))
            .await
            .map_err(|error| format!("terminal create worker failed: {error}"))?;
    if let Some(displaced) = displaced.filter(|session| Some(session) != governed_session.as_ref())
    {
        release_pane_governance(&app, &displaced);
    }
    if result.is_err() {
        // A pane that never started must not leave approval authority behind.
        if let Some(session_id) = governed_session {
            release_pane_governance(&app, &session_id);
        }
    }
    result
}

#[tauri::command]
async fn write_terminal_input(
    manager: tauri::State<'_, TerminalProcessManager>,
    pane_id: String,
    input: String,
) -> Result<TerminalPaneSnapshot, String> {
    let manager = manager.inner().clone();
    tauri::async_runtime::spawn_blocking(move || manager.write(&pane_id, &input).map_err(to_string))
        .await
        .map_err(|error| format!("terminal input worker failed: {error}"))?
}

#[tauri::command]
async fn read_terminal_output(
    manager: tauri::State<'_, TerminalProcessManager>,
    pane_id: String,
    known_output_revision: Option<u64>,
) -> Result<TerminalPaneSnapshot, String> {
    let manager = manager.inner().clone();
    tauri::async_runtime::spawn_blocking(move || {
        manager
            .read(&pane_id, known_output_revision)
            .map_err(to_string)
    })
    .await
    .map_err(|error| format!("terminal read worker failed: {error}"))?
}

#[tauri::command]
async fn resize_terminal_pane(
    manager: tauri::State<'_, TerminalProcessManager>,
    pane_id: String,
    cols: u16,
    rows: u16,
) -> Result<TerminalPaneSnapshot, String> {
    let manager = manager.inner().clone();
    tauri::async_runtime::spawn_blocking(move || {
        manager.resize(&pane_id, cols, rows).map_err(to_string)
    })
    .await
    .map_err(|error| format!("terminal resize worker failed: {error}"))?
}

#[tauri::command]
async fn terminal_pane_has_foreground_job(
    manager: tauri::State<'_, TerminalProcessManager>,
    pane_id: String,
) -> Result<bool, String> {
    let manager = manager.inner().clone();
    tauri::async_runtime::spawn_blocking(move || {
        manager.has_foreground_job(&pane_id).map_err(to_string)
    })
    .await
    .map_err(|error| format!("terminal activity worker failed: {error}"))?
}

